-- You can make apps auto-start here
-- Relevant Hyprland wiki section: https://wiki.hyprland.org/Configuring/Keywords/#executing
-- Generated by hyprlang2lua. Review TODOs before reloading Hyprland.

hl.on("hyprland.start", function()
    hl.exec_cmd("pipewire")
    hl.exec_cmd("mpd --no-daemon")
    hl.exec_cmd("quickshell -p ~/.config/quickshell/dynamic-island")
    hl.exec_cmd("/usr/lib/polkit-kde-agent-1")
    hl.exec_cmd("ydotoold --socket-path /tmp/.ydotool_socket --socket-perm 0666")
    hl.exec_cmd("bash \"$HOME/Coding/lang/shell/setup/pwloopback.sh\"")
    hl.exec_cmd("bash \"$HOME/scr/ConfigColors/run.sh\"")
end)

